                        img.src = finalSrc;
                        const savedImgStyle = { ...(el.imgStyle || {}) };
                        if (el.imgStyle) Object.assign(img.style, el.imgStyle);
                        img.style.clipPath = 'none';
                        img.style.webkitClipPath = 'none';

